argv:
$ErrorActionPreference='SilentlyContinue'; $OutputEncoding=[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new();
$relay='E:\pc-github-relay';
$proc=Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -like '*github_relay.py*' -and $_.CommandLine -like '*E:\pc-github-relay*' } | Select-Object ProcessId,ParentProcessId,CommandLine;
$git=$null; if(Test-Path "$relay\.git"){
  $git=[ordered]@{
    branch=(git -C $relay branch --show-current 2>$null);
    head=(git -C $relay rev-parse HEAD 2>$null);
    remote=(git -C $relay rev-parse origin/agent/pc-github-relay 2>$null);
    status=(git -C $relay status --porcelain 2>$null);
  }
}
$dirs=Get-ChildItem E:\ -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'pc|mcp|boss|control|rehearsal' } | Select-Object -ExpandProperty FullName;
[ordered]@{relay=$git; processes=$proc; dirs=$dirs} | ConvertTo-Json -Depth 5 -Compress
